create or replace function public.runtime_record_memory(p_sh_id uuid, p_content text, p_memory_type text default 'LONG_TERM', p_source text default 'runtime_response', p_confidence numeric default null, p_scope text default 'PRIVATE', p_visibility text default 'OWNER_ONLY', p_lifecycle text default 'CANDIDATE') returns uuid language plpgsql security definer set search_path='public' as $$ declare v_memory_id uuid; begin if auth.uid() is null then raise exception 'MEMORY_REJECTED: authentication required'; end if; if not exists(select 1 from public.sh_instances s where s.sh_id=p_sh_id and s.account_id=public.current_account_id() and s.status <> 'deactivated') then raise exception 'MEMORY_REJECTED: SH not owned by current active account'; end if; if p_content is null or btrim(p_content)='' then raise exception 'MEMORY_REJECTED: content is required'; end if; if p_memory_type not in ('SHORT_TERM','LONG_TERM') then raise exception 'MEMORY_REJECTED: invalid memory_type'; end if; if p_scope not in ('PRIVATE','GENERAL') then raise exception 'MEMORY_REJECTED: invalid scope'; end if; if p_visibility not in ('OWNER_ONLY','SHARED') then raise exception 'MEMORY_REJECTED: invalid visibility'; end if; if p_lifecycle not in ('CANDIDATE','ACTIVE') then raise exception 'MEMORY_REJECTED: invalid lifecycle'; end if; if p_confidence is not null and (p_confidence<0 or p_confidence>1) then raise exception 'MEMORY_REJECTED: invalid confidence'; end if; select memory_id into v_memory_id from public.memories where sh_id=p_sh_id and content=btrim(p_content) and lifecycle in ('CANDIDATE','ACTIVE','UPDATED') order by updated_at desc limit 1 for update; if v_memory_id is not null then update public.memories set occurrence_count=occurrence_count+1,updated_at=now(),confidence=coalesce(p_confidence,confidence),source=coalesce(nullif(p_source,''),source),memory_type=p_memory_type,scope=p_scope,visibility=p_visibility where memory_id=v_memory_id; return v_memory_id; end if; insert into public.memories(sh_id,memory_type,content,source,confidence,scope,visibility,lifecycle,occurrence_count) values(p_sh_id,p_memory_type,btrim(p_content),p_source,p_confidence,p_scope,p_visibility,p_lifecycle,1) returning memory_id into v_memory_id; return v_memory_id; end; $$;

create or replace function public.runtime_record_knowledge_candidate(p_sh_id uuid,p_content text,p_source text,p_origin text,p_provenance jsonb default '{}',p_scope text default 'PRIVATE',p_visibility text default 'OWNER_ONLY',p_confidence numeric default null) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_id uuid; begin if auth.uid() is null then raise exception 'KNOWLEDGE_REJECTED: authentication required'; end if; if not exists(select 1 from public.sh_instances s where s.sh_id=p_sh_id and s.account_id=public.current_account_id() and s.status <> 'deactivated') then raise exception 'KNOWLEDGE_REJECTED: SH not owned by current active account'; end if; if p_content is null or btrim(p_content)='' then raise exception 'KNOWLEDGE_REJECTED: content is required'; end if; if p_source is null or btrim(p_source)='' then raise exception 'KNOWLEDGE_REJECTED: source is required'; end if; if p_origin not in ('MEMORY','EXPLICIT_TEACHING','EXTERNAL_REFERENCE') then raise exception 'KNOWLEDGE_REJECTED: invalid origin'; end if; if p_scope not in ('PRIVATE','GENERAL') then raise exception 'KNOWLEDGE_REJECTED: invalid scope'; end if; if p_visibility not in ('OWNER_ONLY','SHARED') then raise exception 'KNOWLEDGE_REJECTED: invalid visibility'; end if; if p_scope='GENERAL' and p_visibility <> 'SHARED' then raise exception 'KNOWLEDGE_REVIEW_REQUIRED: GENERAL scope requires SHARED visibility'; end if; if p_confidence is not null and (p_confidence<0 or p_confidence>1) then raise exception 'KNOWLEDGE_REJECTED: invalid confidence'; end if; select knowledge_id into v_id from public.knowledge where sh_id=p_sh_id and content=btrim(p_content) and lifecycle='CANDIDATE' order by updated_at desc limit 1 for update; if v_id is not null then update public.knowledge set confidence=coalesce(p_confidence,confidence),provenance=coalesce(provenance,'{}')||coalesce(p_provenance,'{}'),updated_at=now() where knowledge_id=v_id; return v_id; end if; insert into public.knowledge(content,knowledge_class,scope,visibility,source,provenance,confidence,lifecycle,sh_id) values(btrim(p_content),case p_origin when 'EXPLICIT_TEACHING' then 'LEARNED' when 'EXTERNAL_REFERENCE' then 'IMPORTED' else 'TEMPORARY' end,p_scope,p_visibility,btrim(p_source),coalesce(p_provenance,'{}')||jsonb_build_object('origin',p_origin,'acquisition','runtime:p4d:knowledge_candidate'),p_confidence,'CANDIDATE',case when p_scope='PRIVATE' then p_sh_id else null end) returning knowledge_id into v_id; return v_id; end; $$;

create or replace function public.runtime_create_clone(p_agreement_id uuid,p_clone_name text default null) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_agreement public.clone_agreements%rowtype; v_target_account_id uuid; v_source_sh public.sh_instances%rowtype; v_clone_sh_id uuid; v_now timestamptz:=now(); begin if auth.uid() is null then raise exception 'CLONE_REJECTED: authentication required'; end if; v_target_account_id:=public.current_account_id(); if v_target_account_id is null then raise exception 'CLONE_REJECTED: authenticated account not resolved'; end if; select * into v_agreement from public.clone_agreements where agreement_id=p_agreement_id and status='APPROVED' for update; if not found then raise exception 'CLONE_REJECTED: approved agreement required'; end if; select * into v_source_sh from public.sh_instances where sh_id=v_agreement.source_sh_id and account_id=v_agreement.source_account_id and status <> 'deactivated'; if not found then raise exception 'CLONE_REJECTED: source SH ownership boundary failed'; end if; if v_agreement.source_account_id=v_target_account_id then raise exception 'CLONE_REJECTED: source and target accounts must differ'; end if; if not exists(select 1 from public.accounts where account_id=v_target_account_id and lower(trim(email))=lower(trim(v_agreement.target_email))) then raise exception 'CLONE_REJECTED: authenticated recipient does not match intended email'; end if; if v_agreement.target_account_id is not null and v_agreement.target_account_id<>v_target_account_id then raise exception 'CLONE_REJECTED: agreement is already linked to another target account'; end if; if exists(select 1 from public.sh_instances where account_id=v_target_account_id) then raise exception 'CLONE_REJECTED: target account already has an SH'; end if; v_clone_sh_id:=gen_random_uuid(); insert into public.sh_instances(sh_id,account_id,sh_type,is_primary,canonical_name,creator_ref,status,metadata,version,created_at,updated_at) values(v_clone_sh_id,v_target_account_id,'PRIMARY',true,coalesce(nullif(trim(p_clone_name),''),coalesce(v_source_sh.canonical_name,'SH')||' Clone'),'clone:'||v_agreement.source_sh_id::text,'created',jsonb_build_object('origin','CLONE','source_sh_id',v_agreement.source_sh_id,'source_account_id',v_agreement.source_account_id,'agreement_id',v_agreement.agreement_id,'target_email',v_agreement.target_email,'initial_state_semantics','CONTEXT_REFERENCE_TRAITS'),1,v_now,v_now); insert into public.sh_ownership(ownership_id,account_id,sh_id,role,granted_at,evidence_ref,created_at) values(gen_random_uuid(),v_target_account_id,v_clone_sh_id,'OWNER',v_now,'clone_agreement:'||v_agreement.agreement_id::text,v_now); insert into public.sh_clones(clone_sh_id,source_sh_id,agreement_id,status,created_at) values(v_clone_sh_id,v_agreement.source_sh_id,v_agreement.agreement_id,'ACTIVE',v_now); insert into public.memories(sh_id,memory_type,content,source,confidence,scope,visibility,lifecycle,occurrence_count,created_at,updated_at,superseded_by) select v_clone_sh_id,m.memory_type,m.content,m.source,m.confidence,m.scope,m.visibility,case when m.lifecycle='CANDIDATE' then 'ACTIVE' else m.lifecycle end,m.occurrence_count,v_now,v_now,null from public.memories m where m.sh_id=v_agreement.source_sh_id and m.scope <> 'PRIVATE'; insert into public.knowledge(content,knowledge_class,scope,visibility,source,provenance,confidence,version,lifecycle,superseded_by,created_at,updated_at,sh_id) select k.content,k.knowledge_class,k.scope,k.visibility,k.source,jsonb_build_object('clone_origin',jsonb_build_object('source_sh_id',v_agreement.source_sh_id,'source_account_id',v_agreement.source_account_id,'agreement_id',v_agreement.agreement_id,'cloned_at',v_now),'original_provenance',k.provenance),k.confidence,1,case when k.lifecycle='CANDIDATE' then 'ACTIVE' else k.lifecycle end,null,v_now,v_now,case when k.scope='PRIVATE' then v_clone_sh_id else null end from public.knowledge k where k.scope='GENERAL' and k.visibility='SHARED'; insert into public.experiences(sh_id,account_id,experience_type,content,scope,visibility,source_ref,provenance,lifecycle,occurred_at,created_at,updated_at) select v_clone_sh_id,v_target_account_id,e.experience_type,e.content,e.scope,e.visibility,e.source_ref,jsonb_build_object('clone_origin',jsonb_build_object('source_sh_id',v_agreement.source_sh_id,'source_account_id',v_agreement.source_account_id,'agreement_id',v_agreement.agreement_id,'cloned_at',v_now),'original_provenance',e.provenance),e.lifecycle,e.occurred_at,v_now,v_now from public.experiences e where e.sh_id=v_agreement.source_sh_id and e.scope='GENERAL' and e.visibility='SHARED'; update public.clone_agreements set target_account_id=v_target_account_id where agreement_id=v_agreement.agreement_id; return v_clone_sh_id; end; $$;

create or replace function public.runtime_create_recovery_snapshot(p_sh_id uuid) returns uuid language plpgsql security definer set search_path='public' as $$ declare v_snapshot_id uuid; v_account_id uuid; v_manifest jsonb; begin select s.account_id into v_account_id from public.sh_instances s where s.sh_id=p_sh_id and s.account_id=public.current_account_id() and s.status <> 'deactivated'; if v_account_id is null then raise exception 'RECOVERY_REJECTED: SH not owned by current active account'; end if; select jsonb_build_object('identity_root',jsonb_build_object('sh_id',s.sh_id,'account_id',s.account_id,'sh_type',s.sh_type,'is_primary',s.is_primary,'canonical_name',s.canonical_name,'creator_ref',s.creator_ref,'status',s.status,'metadata',s.metadata,'version',s.version),'ownership_root',coalesce((select jsonb_agg(to_jsonb(o)) from public.sh_ownership o where o.sh_id=s.sh_id),'[]'),'memories',coalesce((select jsonb_agg(to_jsonb(m)) from public.memories m where m.sh_id=s.sh_id),'[]'),'conversations',coalesce((select jsonb_agg(to_jsonb(c)) from public.conversations c where c.sh_id=s.sh_id),'[]'),'journey_events',coalesce((select jsonb_agg(to_jsonb(j)) from public.journey_events j where j.sh_id=s.sh_id),'[]'),'knowledge',coalesce((select jsonb_agg(to_jsonb(k)) from public.knowledge k where k.scope='PRIVATE' and k.sh_id=s.sh_id),'[]'),'experiences',coalesce((select jsonb_agg(to_jsonb(e)) from public.experiences e where e.sh_id=s.sh_id),'[]'),'legacy_records',coalesce((select jsonb_agg(to_jsonb(l)) from public.legacy_records l where l.source_sh_id=s.sh_id),'[]'),'captured_at',now()) into v_manifest from public.sh_instances s where s.sh_id=p_sh_id; insert into public.recovery_snapshots(sh_id,account_id,snapshot_kind,manifest) values(p_sh_id,v_account_id,'FULL',v_manifest) returning snapshot_id into v_snapshot_id; return v_snapshot_id; end; $$;
